# coding: utf-8
from pathlib import Path
import json,hashlib
p=Path(__file__).resolve().parent
read=lambda n:json.loads((p/n).read_text())
first,filled,burst,jsc,churn,pressure,features=[read(n) for n in ['native-first-load-results.json','native-filled-first-load-results.json','startup-burst-results.json','startup-jsc-results.json','mixed-native-churn-results.json','native-pressure-results.json','feature-results.json']]
tests=(p/'tests.log').read_text();assert '# tests 2181' in tests and '# pass 2181' in tests and '# fail 0' in tests
snapshot=read('bench-runtime-sha256.json')
current={str(f.relative_to(p/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in (p/'runtime').rglob('*') if f.is_file()};assert current==snapshot['candidate']
assert features['runtimeSHA256']==current and features['version']=='3.2.0' and features['adapter']==16
assert len(first['runs'])==204 and len(filled['runs'])==204 and len(burst['runs'])==96 and len(jsc['runs'])==48
for r in burst['runs']:assert r['runtimeSHA256']==snapshot[r['version']][r['client']+'/script/SpotifyLyrics.Entry.js']
assert all(r['peakLive']==1 and r['pendingAfterDispatch']==0 and r['synchronous']==72 for r in burst['comparisons'] if r['version']=='candidate')
assert all(r['peakLive']==72 and r['pendingAfterDispatch']==72 and r['synchronous']==0 for r in burst['comparisons'] if r['version']=='baseline')
assert sum(r['lyricResponses'] for r in churn['results'])==4800 and all(r['warmHTTP']==0 and r['activeHTTP']==0 and r['maxActiveHTTP']==1 for r in churn['results'])
assert all(r['peakHTTP']==1 and r['peakLiveInvocations']==2 and r['admissionTimers']==0 for r in pressure['comparisons'])
out=['# VerseLyrics 3.2.0 validation and measurements','','The user report is a VPN disconnect after swiping away and reopening Spotify. The reproduced code issue is unnecessary asynchronous completion of local native entry handlers. These measurements validate that change, not the cause of the actual phone disconnect. No device crash record, iPhone scheduler trace or physical VPN acceptance was obtained.','','## Functional verification','','- 2,181 tests pass: all previous 2,097 plus 84 compiled native startup cases. Native local entry work finishes once in the current evaluation; useful metadata/config/card/context/Connect rewrites are retained. Declared/actual body limits, UTF-8/type checks and disabled/unknown/error passthrough are tested.','- Source/translation network work still waits for its actual callbacks. Six sources, bilingual artist matching, mixed Chinese/English, script-only Chinese filtering, vocal-language rules, native colors/timing and static replacement settings remain.','- Egern retains asynchronous native Response/stream reads; the synchronous entry path is for Loon, Surge, Shadowrocket and Quantumult X. No extra request, timer, queue, lease key, capacity or host API.','','## Relaunch burst model','','96 fresh 64 MiB old-space Node processes: six alternating trials per version, four native clients, empty or 48000–60000-character populated cache. Each dispatches 72 compiled entry contexts in one JS turn before a microtask drain, with nine supported routes and 12/40/90 KiB synthetic bodies. Input ownership is released when done is called. Every output body hash matches the baseline. This adverse same-turn scheduling is explicit harness behavior, not a recording of Loon scheduling. Heap/RSS includes Node/compiler/harness and does not capture every transient or native allocation.','','| Client | Cache | Version | Batch ms | Sampled heap growth bytes | Sampled RSS bytes | Peak live entries | Pending after dispatch | Peak owned input bytes |','| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for r in burst['comparisons']:out.append('| %s | %s | %s | %.3f | %d | %d | %d | %d | %d |'%(r['client'],'populated' if r['populated'] else 'empty',r['version'],r['milliseconds'],r['peakHeapGrowth'],r['sampledPeakRSS'],r['peakLive'],r['pendingAfterDispatch'],r['peakRetainedInputBytes']))
loon={}
for populated in [False,True]:
 a=next(r for r in burst['comparisons'] if r['client']=='Loon' and r['populated']==populated and r['version']=='baseline')
 b=next(r for r in burst['comparisons'] if r['client']=='Loon' and r['populated']==populated and r['version']=='candidate')
 loon['populated' if populated else 'empty']={'baselineHeapGrowth':a['peakHeapGrowth'],'candidateHeapGrowth':b['peakHeapGrowth'],'sampledHeapReductionPercent':(1-b['peakHeapGrowth']/a['peakHeapGrowth'])*100,'baselineMs':a['milliseconds'],'candidateMs':b['milliseconds'],'baselinePeakLive':a['peakLive'],'candidatePeakLive':b['peakLive']}
out+=['','The scheduler-independent functional change is synchronous completion. Live-entry/body counts depend on the scheduler. All batch-time regressions above are retained; this release does not claim that every startup or lyric load is faster.','','## macOS JavaScriptCore entry checks','','48 fresh processes: six alternating trials per version for four identical entry fixtures. A marker appended inside the same evaluation checks whether done ran before the evaluation tail. Baseline is asynchronous; candidate is synchronous, with identical rewritten bytes. Footprint and RSS include fixtures, JIT and whole-process overhead. Some footprint/RSS cases can increase; these samples do not establish iPhone or VPN memory.','','| Case | Version | ms | Sampled footprint bytes | Max RSS bytes | Synchronous completion |','| --- | --- | ---: | ---: | ---: | --- |']
for r in jsc['summary']:out.append('| %s | %s | %.3f | %.0f | %.0f | %s |'%(r['case'],r['version'],r['milliseconds'],r['sampledPeakFootprint'],r['maxRSS'],r['synchronous']))
out+=['','## Lyric first-load regression comparisons','','Each table uses 204 fresh Node processes (six alternating trials per version/scenario), one compiled Loon lyric script/VM per process and 32 MiB old-space. Same body hashes and HTTP counts; zero network latency. Populated runs start with 48000–60000 unrelated cache characters. Sampling includes compiler/harness overhead rather than every allocation. These checks cover the retained lyric functionality; the cold-start optimization is in the entry script.']
for title,d in [('Empty cache',first),('Populated cache',filled)]:
 out+=['','### '+title,'','| Case | Baseline ms | Candidate ms | Sampled heap delta bytes |','| --- | ---: | ---: | ---: |']
 for r in d['comparisons']:
  a,b=r['baseline'],r['candidate'];out.append('| %s | %.3f | %.3f | %+d |'%(r['scenario'],a['medianMs'],b['medianMs'],b['sampledMaxHeapBytes']-a['sampledMaxHeapBytes']))
manifest=read('runtime-manifest.json');entry=next(r for r in manifest if r['path']=='Loon/script/SpotifyLyrics.Entry.js')
out+=['','## Bounds and retained behavior','','- Loon entry runtime: 30643 to %d bytes. The core readers, rewritten fields, declared and actual limits remain. The unused asynchronous native entry arrayBuffer wrapper is removed.'%entry['bytes'],'- Twenty native playlists complete 4,800 mixed lyric responses; warm reopen HTTP is 0, active HTTP peaks at 1 and is 0 after completion. Standard/compact capacities are checked on every response.','- Sixteen network-pressure processes retain at most 2 live mock lyric invocations, 1 active HTTP and 0 admission timers. This remains advisory native storage rather than a device-wide atomic lock.','- General features include 60 compiled native invocations. Actual lyric transport remains asynchronous and must settle before completion.','- Limits remain: 256 KiB lyric body, 128 KiB entry body, 96 KiB service reply, 600 lyric rows, 12 source requests and 256 KiB cumulative source bytes; 64 original rows/6800 URL characters per translation batch and a 2.5-second translation window. Standard cache 128 entries/64000 characters; compact 64/32000.','- Native HTTP/decompression buffers and the OS VPN process are outside these script-only measurements. No universal memory ceiling or zero-disconnect guarantee is claimed.','','## Reproduce','','Use the exact lockfile, node build.mjs, python3 package.py RUNTIME_COMMIT 2181, node --test --test-reporter=tap *.test.mjs core/test/*.test.mjs and ruby validate-egern.rb. Run python3 run-measurements-320.py NODE BASELINE_319_SOURCE, then python3 summarize-320.py. Baseline immutable source/runtime commit: 6392d31a69b9c6f5044827d24055ac4dd6222319, source prefix Surge/Development/VerseLyrics319. Runtime hashes are frozen before and after each measurement step.','']
(p/'MEASUREMENTS.md').write_text('\n'.join(out))
report={'version':'3.2.0','adapter':16,'baseline':'3.1.9','baselineSourceCommit':'6392d31a69b9c6f5044827d24055ac4dd6222319','tests':2181,'addedTests':84,'startupBurstFreshNodeProcesses':96,'lyricFirstLoadFreshNodeProcesses':408,'entryJSCFreshProcesses':48,'mixedNativeResponses':4800,'networkPressureProcesses':16,'peakNetworkHTTP':1,'warmHTTP':0,'startupPeakLiveEntriesBefore':72,'startupPeakLiveEntriesAfter':1,'startupPendingAfterDispatchBefore':72,'startupPendingAfterDispatchAfter':0,'loonBurstSamples':loon,'phoneCrashCapture':False,'phoneUIAndVPNAcceptance':False,'runtimeHashes':'bench-runtime-sha256.json','fullMeasurements':'MEASUREMENTS.md'}
(p/'validation-summary.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
